package org.local.donusturucu.qa;
import android.os.Bundle;import android.content.Context;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class SubtitleRoundtrip extends OcrRobustness {
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();Class<?>cl=Class.forName("org.local.donusturucu.SubtitleFiles",true,c.getClassLoader());Method export=cl.getMethod("exportText",File.class),restore=cl.getMethod("restore",File.class,File.class);File root=new File(c.getExternalFilesDir(null),"subtitle-roundtrip-test");root.mkdirs();JSONArray rows=new JSONArray();String timing="00:00:01,250 --> 00:00:03,500",timing2="01:02:03,004 --> 01:02:06,999";String original="7\n"+timing+"\nHello there.\nSecond line.\n\n9\n"+timing2+"\nHow are you?\n\n";
 for(int repeat=1;repeat<=3;repeat++)for(String translated:new String[]{"Merhaba Türkçe","Silav Kurmancî","Hello English","مرحبا العربية","سلام فارسی"}){File srt=new File(root,"original.srt"),text=new File(root,"translated.txt");write(srt,"\uFEFF"+original.replace("\n","\r\n"));String before=hash(srt);String txt=(String)export.invoke(null,srt);if(!txt.equals("Hello there. Second line.\nHow are you?\n"))throw new IOException("Export mismatch");write(text,translated+"\n"+translated+"\n");String textHash=hash(text);String restored=(String)restore.invoke(null,text,srt);if(!restored.equals("7\n"+timing+"\n"+translated+"\n\n9\n"+timing2+"\n"+translated+"\n\n"))throw new IOException("Timing/text mismatch");if(!before.equals(hash(srt))||!textHash.equals(hash(text)))throw new IOException("Original changed");write(text,"one line");boolean rejected=false;try{restore.invoke(null,text,srt);}catch(InvocationTargetException e){rejected="subtitle_line_count".equals(e.getCause().getMessage());}if(!rejected)throw new IOException("Mismatched translation accepted");JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("text",translated);row.put("pass",true);rows.put(row);}
 JSONObject report=new JSONObject();report.put("cases",rows.length());report.put("failures",0);report.put("rows",rows);write(new File(root,"report.json"),report.toString(2));finish(0,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
 static void write(File path,String text)throws Exception{Writer writer=new OutputStreamWriter(new FileOutputStream(path),"UTF-8");try{writer.write(text);}finally{writer.close();}}
}
